ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": "No existen datos con las URN proporcionadas"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

ee:variables.ee:set-variable:
%dw 2.0
import * from dw::core::Arrays
output application/json
var split = p('parameters.statusActiveCod') splitBy ","
var services = vars.clientInformation filter (split contains $.Estado.Principal.Codigo)
---
if(sizeOf(services) > 0)
(payload some ((item) -> 
	if(item.cod_configuracion == null) 
	(services some ($.Servicios_Auxiliares some 
		($.Bundle.Numero_Agrupacion == item.num_agrupacion)
	))
	else 
	((services some ($.Opcionales some 
		($.Codigo_Configuracion == item.cod_configuracion)
	)) or 
	(services some ($.Bundle.Primarios some 
		($.Secundarios some 
			($.Codigo_Configuracion == item.cod_configuracion)
		)
	)) or 
	(services some ($.Servicios_Auxiliares some 
		($.Bundle.Primarios some ($.Secundarios some 
			($.Codigo_Configuracion == item.cod_configuracion)
		))
	)))
))
else false

%dw 2.0
import * from dw::core::Arrays
output application/json
var services = vars.clientInformation filter (upper($.Estado) == upper(p('parameters.statusActive')))
---
if (sizeOf(services) > 0)
(payload some ((item) -> 
	if(item.cod_configuracion == null) 
	(services some ($.Bundles some 
		($.bundle_auxiliar some 
			($.id_catalogo == item.num_agrupacion as String)
	)))
	else 
	((services some ($.Bundles some 
		($.Opcionales.id_opcional == item.cod_configuracion)
	)) or 
	(services some ($.Bundles some 
		($.primarios some ($.secundarios some 
			($.id_secundario == item.cod_configuracion)
		))
	)) or 
	(services some ($.Bundles some 
		($.bundle_auxiliar some 
			($.primarios some ($.secundarios some 
				($.id_secundario == item.cod_configuracion)
			))
		)
	)))
))
else false
